      "answer": "德国后期浪漫主义文学里重视民间文学的流派。一批作家在海德堡创办《隐士报》，主要功绩是对德国民间文学的收集和整理。代表作家阿尔尼姆与布伦塔诺。他们收集编辑民歌集《儿童的号角》。中心人物是格林兄弟，收集《儿童与家庭童话集》，对德国民族文学有重要贡献。",
