      "answer": "英国文学史上称拜伦、雪莱和济慈为“撒旦派”。19世纪初兴起，对“湖畔派”发起抨击，谴责其消极性。蔑视传统、敢于斗争，因而被英国绅士斥为“撒旦”（即魔鬼）。它反映了资产阶级上升时期对个性解放的要求。思想上与“湖畔派”有分歧，艺术上他们继承并发展了“湖畔派”开创的浪漫主义诗歌传统。",
