      "answer": "东方叙事诗是拜伦于1813—1816年创作的一组以东方故事为题材的传奇作品，包括《异教徒》《阿比托斯的新娘》《海盗》《莱拉》《巴里西那》《科林斯的围攻》六部长诗。作品取材于东欧地中海各国和土耳其等地，具有浓厚的异国情调，塑造了一批带有拜伦自身思想性格特征的“拜伦式英雄”，表现其强烈的反叛精神与孤独反抗的个人主义局限。诗歌题材新颖，叙事抒情，意境深远，充满浪漫情调。",
