      "answer": "最初产生于19世纪浪漫主义文学代表拜伦的笔下。他们具有作者本人的思想性格特征。高傲倔强，既不满现实，要求奋起反抗，具有叛逆的性格；但同时又显得忧郁、孤独、悲观，脱离群众，始终找不到正确的出路。拜伦通过他们的斗争表现出对社会不妥协的反抗精神，同时反映出自己的忧郁、孤独和彷徨的苦闷。代表有抒情长诗《恰尔德·哈洛尔德游记》中的哈洛尔德，《东方叙事诗》之《海盗》中的主人公康拉德，哲理剧《曼弗雷德》中的主人公曼弗雷德等。",
