      "answer": "“世纪病”是孕育于18世纪末法国浪漫主义文学中的一种典型形象。这类人物或因王权和神权的恢复而失去信仰、无所追求，或生性孤僻忧郁，与现实格格不入，找不到生命的意义，代表了一代青年的精神状态。夏多布里昂笔下的勒内是第一个表现出“世纪病”的浪漫主义形象，代表还有拜伦《恰尔德·哈洛尔德游记》的哈洛尔德、普希金《叶甫盖尼·奥涅金》的奥涅金、缪塞《一个世纪儿的忏悔》的沃达夫及加缪《局外人》的默尔索。",
