      "answer": "“多余人”是19世纪俄罗斯文学中的一种典型，名称出自屠格涅夫的《多余人日记》。他们属于贵族知识分子，不满上流社会，却不能跳出生活小圈子与人民结合；虽有变革现实的抱负，却缺少实践，生活空虚、性格软弱，缺乏反抗贵族社会的勇气，以忧郁、彷徨的态度对待生活，在社会上无所作为，成为“多余”的人。代表有普希金的《叶甫盖尼·奥涅金》奥涅金、莱蒙托夫《当代英雄》的毕巧林、屠格涅夫的《罗亭》罗亭和冈察洛夫《奥勃洛摩夫》的奥勃洛摩夫。",
