      "answer": "1827年，雨果为自己的剧本《克伦威尔》写了长篇序言，即著名的浪漫派文艺宣言。在序言中雨果反对古典主义的艺术观点，提出了浪漫主义的文学主张：坚持不要公式化地而是具体地表现情节。特别宣扬了滑稽丑怪与崇高优美的对照原则。这篇序言成为声讨古典主义的檄文、浪漫主义运动的重要宣言、浪漫主义文艺理论的经典，在法国文学批评史上占有重要地位。",
