      "answer": "《巴黎圣母院》是雨果最富有浪漫主义小说。它以离奇和对比手法写了一个发生在15世纪法国的故事：巴黎圣母院副主教克洛德道貌岸然，先爱后恨，迫害吉普赛女郎爱斯梅拉达。面目丑陋、心地善良的敲钟人卡西莫多为救女郎舍身。小说揭露了宗教的虚伪，宣告禁欲主义的破产，歌颂了下层劳动人民的善良、友爱、舍己为人，反映了雨果的人道主义思想。小说是运用浪漫主义对照原则的艺术范本。",
