      "answer": "《别尔金小说集》由俄国作家普希金所作，包括《射击》《暴风雪》《棺材匠》《村姑小姐》及《驿站长》。展示了19世纪20年代俄国城乡生活的画面，塑造了一系列的典型形象：贵族、军官、城市手艺人等。《驿站长》一文成功地塑造了俄国文学史上第一个“小人物”维林形象，揭露了当时俄国社会最底层的人物的悲惨生活。",
