      "answer": "是普希金创作的长篇诗体小说，是俄国现实主义文学的基石，确立了俄罗斯语言规范。作品真实反映19世纪20年代俄国社会生活，表现当时青年的苦闷、探求和觉醒，提出了许多重要的社会问题。奥涅金概括了受进步思想影响却未能跳出狭小圈子的贵族青年的思想面貌和悲剧命运，是俄国文学中第一个“多余人”形象。全篇以诗体写成，兼有诗和小说的特点，客观描写与主观抒情有机交融。",
