      "answer": "1. 强烈的个人主义倾向。文化内核上是古希腊罗马人本主义传统的延续，文化血脉上与文艺复兴运动的“人”的发现相承相通。张扬个性，塑造充满欲望的“自我”，传达出现代人要求摆脱传统与文明束缚的强烈倾向。\n2. 强调感情的抒发，有较强的主观性。反对古典主义文学崇尚理性的法则，主张从情感与想象等出发，强调创作的绝对自由。\n3. 注重描写和歌颂大自然。接受卢梭“返回自然”的主张，崇尚自然。反对古典主义只注重描写历史题材和宫廷生活，着力表现自然景物和乡间的淳朴生活。\n4. 善用夸张手法。侧重描写理想世界以及作家想象中的、理想化了的人物。这些人物又常常带有个人主义色彩，给人以超然不群、高不可攀的感觉，拜伦式英雄就是这类典型。\n5. 重视民间文学。重视民族传统和民间文学，尤其是中世纪的。感情真挚，想象丰富，形式自由，语言不拘一格。",
