      "answer": "《巴黎圣母院》的情节始终围绕三个人展开：善良美丽的少女爱斯梅拉达，残忍虚伪的圣母院副主教克洛德和外表丑陋、内心崇高的敲钟人卡西莫多。\n（1）爱斯梅拉达是雨果塑造的理想人物，是人性美的象征。她纯洁善良，酷爱自由，热情豪爽，品格坚贞。她从内心的善良愿望出发对待任何人。对于误入乞丐王国的诗人甘果瓦，她挽救了他的生命；她还不计前嫌送水给受刑时的卡西莫多；她对爱情抱着至死不渝的信念，丝毫不怀疑心上人的背叛，不允许别人说一句他的坏话；面对克洛德的淫威，她宁死不屈。\n她的毁灭，是对封建专制残酷统治和教会邪恶势力的有力控诉，同时也唤起了人们对真善美的追求。\n（2）卡西莫多是巴黎圣母院的敲钟人，雨果理想中“善”的化身，是雨果根据美丑对照原则创造的人物形象。\n他外表丑陋，有着丑到极点的相貌：几何形的脸，四面体的鼻子，马蹄形的嘴，参差不齐的牙齿，独眼，耳聋，驼背，似乎上帝将所有的不幸都降临在了他的身上，受尽嘲弄。但内心崇高，是一个富有正义感、富于感情的人。他对爱斯梅拉达的爱慕是一种混合着感激、同情和尊重的柔情，一种无私的、永恒的、高贵纯朴的爱，完全不同于克洛德那种邪恶的占有欲，也不同于花花公子弗比斯的逢场作戏。\n雨果通过这一形象，树立起一个人类灵魂美的典型。这一形象还体现了善战胜恶，真诚战胜虚伪的理论。\n（3）克洛德是巴黎圣母院的副主教，一个双重性格的人物。\n一方面，他是宗教恶势力的代表，道貌岸然，内心阴险毒辣，为满足自己欲念不择手段：他出于淫欲指使卡西莫多劫持爱斯梅拉达；出于嫉妒刺伤弗比斯却嫁祸于爱斯梅拉达；他因得不到爱丝梅拉达的爱情而将她置于死地。\n另一方面，他又是宗教禁欲主义的牺牲品，长久的禁欲扭曲了他的灵魂。他越是意识到自己失去了人间的欢乐，便越是仇恨世人，仇视世间一切美好的事物。这是小说中最有深度的人物。\n（4）弗比斯是一位年轻的军官。有着与希腊神话中描述美男子一样的容貌与体魄，但同样也是一个喜欢美与浪漫的风流男人。他喜欢美丽女人，却从不忠贞，在花丛中流连。因此，他是外表俊美，内心丑陋。\n他以惯用的情话骗取少女的爱情；但她因他被刺而被判死刑时，他根本不愿出庭证明她无罪，卑劣面目昭然若揭。\n（5）主题思想：小说揭露了宗教的虚伪，宣告禁欲主义的破产，歌颂了下层劳动人民的善良、友爱、舍己为人，反映了雨果的人道主义思想。\n艺术地再现了法王路易十一统治时期的真实历史，宫廷与教会如何狼狈为奸压迫人民群众，人民群众怎样同两股势力英勇斗争。\n小说中的反叛者吉普赛女郎爱斯梅拉达和面容丑陋的卡西莫多是作为真正的美的化身展现在读者面前的，而人们在副主教克洛德和贵族军人弗比斯身上看到的则是残酷、空虚的心灵和罪恶的情欲。\n作者将可歌可泣的故事和生动丰富的戏剧性场面有机地连缀起来，使这部小说具有很强的可读性。小说是运用浪漫主义对照原则的艺术范本。小说的发表，使雨果的名声更加远扬。",
