      "answer": "《巴黎圣母院》最集中最典型地反映了雨果的浪漫主义文艺观。其鲜明的浪漫主义特色表现在：\n第一，离奇的情节。这部小说情节曲折离奇，富有戏剧性，充满了现实生活中不可能有的巧合、夸张和怪诞。如：卡西莫多的劫法场，抵御千军万马的进攻；乞丐王国的某些非常规法则；卡西莫多的尸骨一被分开就化为灰尘等。这些曲折多变，但在本质上又是真实的情节，大大加强了小说的戏剧性，从而增强了小说的感染力。\n第二，非凡的人物。小说的人物是浪漫主义的典型人物：爱斯梅拉达的美貌和人格力量是非凡的；卡西莫多的非凡则表现在他可怕的外貌，奇特的举动，巨人般的体力，以及对爱斯梅拉达高尚而充满自我牺牲的爱情及表达方式；克罗德的禁欲和纵欲的矛盾等。\n这些人物的特点，表现了雨果独具的浪漫主义特征，即追求夸张、想象而不求细节的真实，不求酷似现实。\n第三，强烈的对比。作为一种美学理想，对比原则是雨果浪漫主义最重要的特征，贯穿着小说的始终。\n首先是巴黎城市和圣母院和谐美丽的自然环境与人民阴暗不幸的生活构成鲜明对比，这样更突出暴露了封建暴政的黑暗。其次是草菅人命，任意诬陷的封建王朝与尊重人权，公正廉明的“乞丐王国”的对比。\n最主要的是人物形象的对比：正面与反面人物的对比—爱斯梅拉达和卡西莫多是善良，真诚和美好的人性的代表；克罗德、弗比斯则是自私、冷酷和丑恶的人性的代表、善与恶十分鲜明地分别体现在这两组人物身上，产生强烈的对照。还有正面与正面，反面与反面人物之间的对比以及人物自身对比，如卡西莫多外貌与心灵的对比等。对比原则的运用使得小说的情节和人物显得更奇特，主题更鲜明，突出。\n最后，作者以浓烈的色彩描绘了中世纪特征鲜明而绚丽的城市图景，给读者展现了一个充满绚烂和奇特色彩的世界。",
