      "answer": "农民出身的贫穷工人冉阿让因偷面包被人抓住，判了5年徒刑。他几次越狱，结果为了一块面包坐了19年的牢。\n出狱之后，冉阿让到处遭人白眼，没有工作，没有饭吃，他发誓一定要向社会复仇。这时，一个叫米里哀的主教感化了他，他决心行善积德，做一个好人。\n他化名马德兰，在一个城市办了个工厂，成为富翁。他为贫穷的人提供就业机会，给他们饭吃，给他们房子，他处处乐于助人，被市民们选为市长。\n这时，市里来了一个叫芳汀的姑娘，她原是农村姑娘，到城里做工，被人诱骗生下一个女儿。她把女儿珂赛特寄养在一个旅店老板家中，老板是个恶棍，趁机敲诈她，芳汀被迫卖掉美丽的头发、漂亮的牙齿，又卖身当了妓女，最后贫困交加，病得奄奄一息，冉阿让听说后立即去照顾她，答应在她死后抚养她女儿珂赛特。\n这时，警察沙威正追捕失踪多年的苦役犯冉阿让，在马德兰市，他抓住了一个贫穷的工人，认为他就是冉阿让，准备把他送进监狱，为了救这个无辜的工人，冉阿让挺身而出，主动承认了自己的身份。他又落入警察手中，去监狱的路上，他设法逃脱了。\n冉阿让马上找到珂赛特，带着她躲在一个偏僻的修道院里。多年过去了，珂赛特已长大成人，和一个共和党人马吕斯相爱。1832年，巴黎爆发了共和党领导的起义，遭到七月王朝的血腥镇压，马吕斯身负重伤，冉阿让冒着生命危险通过下水道把他救了出来。\n这时，沙威混进起义者队伍进行侦察，被抓住后判处死刑，由冉阿让去执行命令，枪毙沙威，但冉阿让却把沙威放了。沙威在冉阿让的高尚人格前羞愧难容，投河自杀。\n珂赛特和马吕斯结婚了，冉阿让一个人过着孤独的日子，最后他死在了珂赛特的怀里。\n反映了人类与邪恶之间不懈的斗争，人类本性是纯洁善良的，将一同走向幸福，但要经过苦难的历程。雨果力图表现严刑酷法只能使人更加邪恶，应根据人道主义精神用道德感化的方法处理，他借主人公之口说道“最高的法律是良心”。他自称这是“一部宗教作品”。\n更主要的是，雨果要在小说里写出下层人民悲惨的命运。在他看来，大革命后的半个世纪的不同阶段，下层人民的处境同样都悲惨艰难，并无变化，他以冉阿让、芳汀与珂赛特的故事说明了这一点。\n他在小说的序里就指出了\"本世纪\"的三个问题：\"贫穷使男子潦倒，饥饿使妇女堕落，黑暗使儿童羸弱\"。\n小说通过冉阿让、芳汀、珂赛特的遭遇给这段话作了形象的诠释，深刻地反映了下层人民的悲惨命运。",
